const src = $json.body?.currentMessage ?? $json.event ?? $json.currentMessage ?? $json;
const clean = v => v === undefined || v === null ? null : String(v).trim();
const normalizePhone = v => { let digits=String(v??'').replace(/\D/g,''); if(digits.length===11&&digits.startsWith('1'))digits=digits.slice(1); return digits||null; };
const attachments = Array.isArray(src.attachments) ? src.attachments.map((a, index) => ({ filename: clean(a.filename ?? a.name), content_type: clean(a.content_type ?? a.contentType ?? a.mimeType), size: Number.isFinite(Number(a.size)) ? Number(a.size) : null, url: clean(a.url), s3_key: clean(a.s3_key ?? a.s3Key), uploaded_at: clean(a.uploaded_at ?? a.uploadedAt), source_index: index })) : [];
const sender = clean(src.sender ?? src.from ?? src.sender_number);
const recipient = clean(src.recipient ?? src.to ?? src.recipient_number);
const content = clean(src.content ?? src.input_message ?? src.message) ?? '';
const messageId = clean(src.message_id ?? src.messageId);
const claimedDealerId = clean(src.dealer_id ?? src.dealerId);
const explicitParent = clean(src.parent_conversation ?? src.parentConversation ?? src.parent_message_id ?? src.parentMessageId);
const rawReceivedAt = clean(src.date ?? src.timestamp ?? src.received_at);
const receivedAtValid = !!rawReceivedAt && Number.isFinite(Date.parse(rawReceivedAt));
const receivedAt = receivedAtValid ? new Date(Date.parse(rawReceivedAt)).toISOString() : new Date().toISOString();
const errors = [];const warnings=[];
if (!sender) errors.push('MISSING_SENDER');
if (!recipient) errors.push('MISSING_RECIPIENT');
if (!messageId) errors.push('MISSING_MESSAGE_ID');
if (!content && attachments.length === 0) errors.push('EMPTY_MESSAGE');
if(rawReceivedAt&&!receivedAtValid)warnings.push('INVALID_RECEIVED_AT_DEFAULTED_TO_NOW');
return [{ json: { schema_version: '8.0', channel: 'sms', event: { type: 'inbound_message', message_id: messageId, parent_message_id: explicitParent, content, sender, recipient, received_at: receivedAt, attachments, raw_dealer_id: claimedDealerId }, identity: { dealer_id: null, customer_id: null, lead_id: null, conversation_id: null, parent_message_id: null }, context: { resolution: { valid_input: errors.length === 0, errors, warnings, claimed_dealer_id: claimedDealerId, normalized_sender_phone:normalizePhone(sender), normalized_recipient_phone:normalizePhone(recipient), ambiguous:false } }, intelligence: {}, inventory: null, decision: {}, response: {} } }];

const envelope = JSON.parse(JSON.stringify($node['Normalize Input'].json));
const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length && r._id);
const claimed = envelope.context.resolution.claimed_dealer_id;
const exact = claimed ? rows.filter(r => String(r._id) === claimed || String(r.dealer_id ?? '') === claimed) : rows;
const candidates = exact.length ? exact : rows;
if (candidates.length === 1) {
  const dealer = candidates[0];
  envelope.identity.dealer_id = String(dealer._id ?? dealer.dealer_id);
  envelope.context.dealer = {
    id: envelope.identity.dealer_id,
    bot_name: dealer.dealer_account_information?.ai_bot_name ?? dealer.ai_bot_name ?? null,
    store_name: dealer.dealer_account_information?.dealership_name ?? dealer.name ?? null,
    store_phone: dealer.dealer_account_information?.sms_conversion_phone ?? envelope.event.recipient,
    store_address: dealer.dealer_account_information?.address ?? dealer.address ?? null,
    store_website: dealer.dealer_account_information?.website ?? dealer.website ?? null,
    manager_name: dealer.dealer_account_information?.manager_name ?? dealer.manager_name ?? null,
    store_hours: dealer.dealer_account_information?.store_hours ?? dealer.store_hours ?? null,
    trade_url: dealer.dealer_account_information?.trade_in_appraisal_url ?? dealer.trade_in_appraisal_url ?? null,
    finance_url: dealer.dealer_account_information?.credit_finance_application_url ?? dealer.credit_finance_application_url ?? null
  };
} else {
  envelope.context.resolution.errors.push(candidates.length ? 'AMBIGUOUS_DEALER_PHONE' : 'DEALER_NOT_FOUND');
  if(candidates.length)envelope.context.resolution.ambiguous=true;
}
envelope.context.resolution.dealer_match_count = candidates.length;
envelope.context.resolution.valid = envelope.context.resolution.valid_input && candidates.length === 1;
return [{ json: envelope }];

const envelope = JSON.parse(JSON.stringify($node['Validate Dealer Resolution'].json));
const truthy = v => v === true || v === 1 || v === '1' || String(v).toLowerCase() === 'true';
const id = v => v?.$oid ? String(v.$oid) : v===undefined||v===null ? null : String(v);
const timeOf = r => {const value=r.timestamp??r.date??r.created_at??r.createdAt;const ms=Date.parse(value);return Number.isFinite(ms)?ms:null;};
const eventTime=Date.parse(envelope.event.received_at);
const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length && (r._id || r.message_id));
const asOfRows=rows.filter(r=>{const time=timeOf(r);return time!==null&&time<=eventTime&&id(r.message_id)!==id(envelope.event.message_id);});
asOfRows.sort((a,b)=>{const byTime=timeOf(b)-timeOf(a);if(byTime)return byTime;return String(id(a._id)??id(a.message_id)??'').localeCompare(String(id(b._id)??id(b.message_id)??''));});
const usable = asOfRows.filter(r => !truthy(r.internal_use) && !truthy(r.is_note??r.isNote) && (r.use_replies_for_ai === undefined || r.use_replies_for_ai === null || truthy(r.use_replies_for_ai)));
const explicit=id(envelope.event.parent_message_id);
const explicitValid=!!explicit&&usable.some(r=>[r.parent_conversation,r.parent_message_id,r.message_id,r._id].some(value=>id(value)===explicit));
if(explicit&&!explicitValid)envelope.context.resolution.warnings.push('EXPLICIT_PARENT_NOT_FOUND_AS_OF_EVENT');
const latest=usable[0]??null;
const parent=explicitValid?explicit:id(latest?.parent_conversation??latest?.parent_message_id??latest?.message_id??latest?._id)??envelope.event.message_id;
const linked=usable.find(r=>r.lead_id)??null;
envelope.identity.conversation_id=parent;
envelope.identity.parent_message_id=parent;
envelope.identity.lead_id=id(linked?.lead_id);
envelope.context.resolution.conversation_record_count=rows.length;
envelope.context.resolution.as_of_conversation_record_count=asOfRows.length;
envelope.context.resolution.usable_conversation_record_count=usable.length;
envelope.context.resolution.future_conversation_record_count=rows.filter(r=>{const time=timeOf(r);return time!==null&&time>eventTime;}).length;
return [{ json: envelope }];

const envelope = JSON.parse(JSON.stringify($node['Assemble Customer Resolution'].json));
const id=v=>v?.$oid?String(v.$oid):v===undefined||v===null?null:String(v);
const normalizePhone=v=>{let digits=String(v??'').replace(/\D/g,'');if(digits.length===11&&digits.startsWith('1'))digits=digits.slice(1);return digits||null;};
const rows=$input.all().map(i=>i.json).filter(r=>r&&Object.keys(r).length&&r._id);
const linkedId=id(envelope.identity.lead_id);
const parent=id(envelope.identity.parent_message_id);
const customerId=id(envelope.identity.customer_id);
const phone=envelope.context.resolution.normalized_sender_phone;
const tiers=[
  rows.filter(r=>linkedId&&id(r._id)===linkedId),
  rows.filter(r=>parent&&id(r.parent_message_id)===parent),
  rows.filter(r=>customerId&&id(r.customer_id)===customerId),
  rows.filter(r=>phone&&[r.phone,r.phone_number].some(value=>normalizePhone(value)===phone))
];
const matches=tiers.find(group=>group.length)??[];
const lead=matches.length===1?matches[0]:null;
envelope.identity.lead_id=null;
if(lead){
  envelope.identity.lead_id=id(lead._id);
  envelope.identity.customer_id=id(lead.customer_id)??envelope.identity.customer_id;
  envelope.context.lead={id:id(lead._id),customer_id:envelope.identity.customer_id,name:lead.name??lead.customer_name??null,email:lead.email??null,phone:lead.phone??lead.phone_number??envelope.event.sender,vin:lead.vin??lead.vehicle_vin??null,make:lead.make??lead.vehicle_make??null,model:lead.model??lead.vehicle_model??null,year:lead.year??lead.vehicle_year??null,status:lead.status??null};
  const linkedCustomer=$items('Resolve Customer').map(i=>i.json).find(c=>id(c?._id)===envelope.identity.customer_id);
  if(linkedCustomer){
    const primaryEmail=Array.isArray(linkedCustomer.emails)?(linkedCustomer.emails.find(x=>x?.is_primary)?.value??linkedCustomer.emails[0]?.value??null):null;
    const primaryPhone=Array.isArray(linkedCustomer.phones)?(linkedCustomer.phones.find(x=>x?.is_primary)?.value??linkedCustomer.phones[0]?.value??null):null;
    envelope.context.customer={id:id(linkedCustomer._id),name:linkedCustomer.name??null,email:primaryEmail,phone:primaryPhone};
  }
}
envelope.context.resolution.lead_match_count=rows.length;
envelope.context.resolution.lead_resolution_candidate_count=matches.length;
envelope.context.resolution.lead_ambiguous=matches.length>1;
if(matches.length>1){envelope.context.resolution.ambiguous=true;envelope.context.resolution.warnings.push('AMBIGUOUS_LEAD_MATCH');}
return [{json:envelope}];

const envelope = JSON.parse(JSON.stringify($node['Resolve Conversation'].json));
const id=v=>v?.$oid?String(v.$oid):v===undefined||v===null?null:String(v);
const customers=$input.all().map(i=>i.json).filter(r=>r&&Object.keys(r).length&&r._id);
const customer=customers.length===1?customers[0]:null;
if(customer){
  const primaryEmail=Array.isArray(customer.emails)?(customer.emails.find(x=>x?.is_primary)?.value??customer.emails[0]?.value??null):null;
  const primaryPhone=Array.isArray(customer.phones)?(customer.phones.find(x=>x?.is_primary)?.value??customer.phones[0]?.value??null):null;
  envelope.identity.customer_id=id(customer._id);
  envelope.context.customer={id:id(customer._id),name:customer.name??null,email:primaryEmail,phone:primaryPhone};
}
envelope.context.resolution.customer_match_count=customers.length;
envelope.context.resolution.customer_ambiguous=customers.length>1;
if(customers.length>1){envelope.context.resolution.ambiguous=true;envelope.context.resolution.warnings.push('AMBIGUOUS_CUSTOMER_PHONE');}
return [{json:envelope}];

const envelope=JSON.parse(JSON.stringify($json));
const hasPrior=(envelope.context?.resolution?.usable_conversation_record_count??0)>0;
const resolved=!!envelope.context?.resolution?.valid;
const hasLead=!!envelope.identity?.lead_id;
const hasCustomer=!!envelope.identity?.customer_id;
envelope.context.resolution.create_lead=resolved&&!hasLead&&!hasCustomer&&!hasPrior&&!envelope.context.resolution.ambiguous;
envelope.context.resolution.update_lead=hasLead;
envelope.context.resolution.completed_at=new Date().toISOString();
return [{json:envelope}];
